const dataFile = process.env.TODO_DATA_FILE || path.join(process.cwd(), "data", "todos.json");

function ensure() {
  fs.mkdirSync(path.dirname(dataFile), { recursive: true });
  if (!fs.existsSync(dataFile)) fs.writeFileSync(dataFile, "[]");
